layer.css:
[data-ryt="pitch"] { color: var(--ryt-muted); background-color: var(--ryt-surface); border-left: 5px solid rgb(219, 219, 219); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 24px; padding-bottom: 20px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(250, 250, 250); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 24px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(54, 54, 54); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: 1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(54, 54, 54); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="brand"] { color: rgb(54, 54, 54); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(54, 54, 54); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(54, 54, 54); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(54, 54, 54); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 12px; padding-bottom: 8px; padding-left: 12px; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(54, 54, 54); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(54, 54, 54); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-muted); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 0.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; padding-bottom: 6px; position: relative }
[data-ryt="rec-card"] [data-ryt="title"]::after { content: ""; display: block; position: absolute; width: 100%; height: 2px; color: var(--ryt-muted); background-color: rgb(250, 176, 5); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 0.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.25s ease-out; -webkit-text-fill-color: var(--ryt-muted); bottom: 0px; left: 0px }
[data-ryt="nav"] a:hover { background-color: var(--ryt-surface); color: rgb(54, 54, 54) }
